## 📘 Singly Linked List in C (All Operations)

```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;
    struct Node* next;
};

// Create a new node with given data
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

/* ---------------- BASIC OPERATIONS ---------------- */

// Insert at the beginning
void insertAtBeginning(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    newNode->next = *head;   // New node points to old head
    *head = newNode;         // Update head to new node
}

// Insert at the end
void insertAtEnd(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    if (*head == NULL) {     // If list is empty
        *head = newNode;
        return;
    }
    struct Node* temp = *head;
    while (temp->next != NULL) { // Traverse to last node
        temp = temp->next;
    }
    temp->next = newNode;
}

// Insert after a given key
void insertAfter(struct Node* head, int key, int data) {
    struct Node* temp = head;
    while (temp != NULL && temp->data != key) {
        temp = temp->next;
    }
    if (temp == NULL) {
        printf("Key %d not found!\n", key);
        return;
    }
    struct Node* newNode = createNode(data);
    newNode->next = temp->next;
    temp->next = newNode;
}

// Delete first node
void deleteFirst(struct Node** head) {
    if (*head == NULL) return;  // Empty list
    struct Node* temp = *head;
    *head = (*head)->next;
    free(temp);
}

// Delete last node
void deleteLast(struct Node** head) {
    if (*head == NULL) return;  // Empty list
    if ((*head)->next == NULL) { // Only one node
        free(*head);
        *head = NULL;
        return;
    }
    struct Node* temp = *head;
    while (temp->next->next != NULL) { // Reach 2nd last node
        temp = temp->next;
    }
    free(temp->next);
    temp->next = NULL;
}

// Delete node with given key
void deleteByKey(struct Node** head, int key) {
    if (*head == NULL) return;

    // If head node itself holds the key
    if ((*head)->data == key) {
        struct Node* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }

    struct Node* temp = *head;
    while (temp->next != NULL && temp->next->data != key) {
        temp = temp->next;
    }

    if (temp->next == NULL) {
        printf("Key %d not found!\n", key);
        return;
    }

    struct Node* nodeToDelete = temp->next;
    temp->next = temp->next->next;
    free(nodeToDelete);
}

// Search for a value
int search(struct Node* head, int key) {
    struct Node* temp = head;
    while (temp != NULL) {
        if (temp->data == key) return 1; // Found
        temp = temp->next;
    }
    return 0; // Not found
}

// Count number of nodes
int countNodes(struct Node* head) {
    int count = 0;
    struct Node* temp = head;
    while (temp != NULL) {
        count++;
        temp = temp->next;
    }
    return count;
}

// Reverse the linked list
void reverse(struct Node** head) {
    struct Node* prev = NULL;
    struct Node* curr = *head;
    struct Node* next = NULL;
    while (curr != NULL) {
        next = curr->next;   // Save next
        curr->next = prev;   // Reverse pointer
        prev = curr;         // Move prev
        curr = next;         // Move curr
    }
    *head = prev; // Update head
}

// Print the linked list
void printList(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

/* ---------------- TESTING ---------------- */
int main() {
    struct Node* head = NULL;

    insertAtBeginning(&head, 10);
    insertAtBeginning(&head, 5);
    insertAtEnd(&head, 20);
    insertAfter(head, 10, 15);

    printf("Linked List: ");
    printList(head);

    deleteFirst(&head);
    deleteLast(&head);
    deleteByKey(&head, 15);

    printf("After deletions: ");
    printList(head);

    printf("Count = %d\n", countNodes(head));
    printf("Search 20: %s\n", search(head, 20) ? "Found" : "Not Found");

    reverse(&head);
    printf("Reversed List: ");
    printList(head);

    return 0;
}
```

